// The store of the program API; components read it and write the user's input into it.
const CoreContext = createContext<UiCore | null>(null);
// 0 for the screen, 1 inside a modal (while a modal is shown only its components get clicks).
const LayerContext = createContext(0);

/** True while the error dialog is open: the UI behind it does not react to keys. */
function useBlocked(): () => boolean {
  const core = useContext(CoreContext);
  return () => !!core && core.pending.length > 0;
}

// Makes the element behind the returned ref clickable: `onClick` gets the cell that was hit.
function useHit(onClick: (x: number, y: number) => void) {
  const core = useContext(CoreContext);
  const layer = useContext(LayerContext);
  const ref = useRef<DOMElement>(null);
  const latest = useRef(onClick);
  latest.current = onClick;
  useEffect(() => core?.addHit({ ref, layer, cb: (x, y) => latest.current(x, y) }), [core, layer]);
  return ref;
}

// Scrolls the screen so that a focused component is in view.
function useReveal(ref: { current: unknown }, active: boolean) {
  const core = useContext(CoreContext);
  useEffect(() => {
    if (!active || !core) return;
    const r = rectOf(ref.current);
    if (r) core.reveal(r.y, r.y + r.height);
  }, [active, core]);
}

// The content of the screen: taller than the terminal it is shifted up (negative margin) inside a
// clipping box; a thin scroll bar shows on the right while there is something to scroll.
function ScrollArea({ children, ...props }: BoxProps & { children?: ReactNode }) {
  const core = useContext(CoreContext);
  const view = useRef<DOMElement>(null);
  const content = useRef<DOMElement>(null);
  useEffect(() => {
    if (!core || !view.current || !content.current) return;
    core.viewRef = view;
    const box = measureElement(view.current);
    core.setMetrics(measureElement(content.current).height, box.height, box.width);
  });
  const offset = core ? core.scroll : 0;
  const rows = core ? core.viewHeight : 0;
  const total = core ? core.contentHeight : 0;
  const thumb = Math.max(1, Math.round((rows * rows) / Math.max(1, total)));
  const top = total > rows ? Math.round((offset / (total - rows)) * (rows - thumb)) : 0;
  return (
    <Box flexGrow={1} flexDirection="row">
      <Box ref={view} flexGrow={1} flexDirection="column" overflow="hidden">
        <Box ref={content} flexShrink={0} minHeight={rows} marginTop={-offset} {...props}>
          {children}
        </Box>
      </Box>
      {total > rows ? (
        <Box flexDirection="column" width={1} flexShrink={0}>
          {Array.from({ length: rows }, (_, i) => (
            <Text key={i} dimColor={i < top || i >= top + thumb}>
              {i >= top && i < top + thumb ? "█" : "│"}
            </Text>
          ))}
        </Box>
      ) : null}
    </Box>
  );
}

// A modal: it is centred over the visible screen (not scrolled with the content), its box
// swallows clicks and its components are the only clickable ones.
function ModalBox({ children, ...props }: BoxProps & { children?: ReactNode }) {
  const core = useContext(CoreContext);
  const ref = useRef<DOMElement>(null);
  useEffect(() => core?.addHit({ ref, layer: 1, modal: true, cb: () => {} }), [core]);
  const wide = typeof props.width === "number" ? props.width : 0;
  const high = typeof props.height === "number" ? props.height : 0;
  const scroll = core ? core.scroll : 0;
  const left = core && wide ? Math.max(0, Math.floor((core.viewWidth - wide) / 2)) : (props.marginLeft ?? 0);
  const top = core && high ? Math.max(0, Math.floor((core.viewHeight - high) / 2)) + scroll : (props.marginTop ?? 0) + scroll;
  return (
    <LayerContext.Provider value={1}>
      <Box ref={ref} {...props} marginLeft={left} marginTop={top}>
        {children}
      </Box>
    </LayerContext.Provider>
  );
}


// Something Tab can focus; Enter or Space (or a click) presses it.
function Focusable({ onPress, center, children }: { onPress: () => void; center?: boolean; children: (focused: boolean) => ReactNode }) {
  const id = useId();
  const { isFocused, focus } = useFocus({ id });
  const blocked = useBlocked();
  useInput(
    (input, key) => {
      if (blocked()) return;
      if (key.return || input === " ") onPress();
    },
    { isActive: isFocused },
  );
  const ref = useHit(() => {
    focus(id);
    onPress();
  });
  useReveal(ref, isFocused);
  return (
    <Box ref={ref} flexGrow={1} {...(center ? { justifyContent: "center" as const } : {})}>
      {children(isFocused)}
    </Box>
  );
}


// True while a text field has the focus, so that typing "q" does not quit the app.
let typing = false;

// A one-line text field (the cursor is always at the end); a click focuses it. The text is
// indented by two cells like Textual's Input.
function Field({ value, onChange, onSubmit, placeholder, textProps }: { value: string; onChange: (value: string) => void; onSubmit?: () => void; placeholder: string; textProps?: TextProps }) {
  const id = useId();
  const { isFocused, focus } = useFocus({ id });
  const blocked = useBlocked();
  useEffect(() => {
    typing = isFocused;
    return () => {
      typing = false;
    };
  }, [isFocused]);
  useInput(
    (input, key) => {
      if (blocked()) return;
      if (key.return) onSubmit?.();
      else if (key.backspace || key.delete) onChange([...value].slice(0, -1).join(""));
      else if (key.ctrl || key.meta || key.tab || key.escape || key.upArrow || key.downArrow || key.leftArrow || key.rightArrow) return;
      else if (input) onChange(value + input);
    },
    { isActive: isFocused },
  );
  const ref = useHit(() => focus(id));
  useReveal(ref, isFocused);
  return (
    <Box ref={ref} flexGrow={1} paddingLeft={2}>
      <Text {...textProps}>
        {value ? value : <Text dimColor>{placeholder}</Text>}
        {isFocused ? <Text inverse> </Text> : null}
      </Text>
    </Box>
  );
}


// Closed it shows the value; Enter or a click opens the list (arrow keys or a click to choose, Esc to close).
function Dropdown({ options, value, onChange, disabled, textProps }: { options: string[]; value: string; onChange: (value: string) => void; disabled?: boolean; textProps?: TextProps }) {
  const id = useId();
  const { isFocused, focus } = useFocus({ id });
  const blocked = useBlocked();
  const [open, setOpen] = useState(false);
  useInput(
    (_input, key) => {
      if (key.return && !disabled && !blocked()) setOpen(true);
    },
    { isActive: isFocused && !open },
  );
  useInput(
    (_input, key) => {
      if (key.escape) setOpen(false);
    },
    { isActive: open },
  );
  const ref = useHit((_x, y) => {
    focus(id);
    if (disabled) return;
    const top = rectOf(ref.current)?.y ?? y;
    if (!open) setOpen(true);
    else if (y - top >= 0 && y - top < options.length) {
      onChange(options[y - top]);
      setOpen(false);
    }
  });
  useReveal(ref, isFocused);
  return (
    <Box ref={ref} flexGrow={1}>
      {open ? (
        <SelectInput
          items={options.map((o) => ({ label: o, value: o }))}
          initialIndex={Math.max(0, options.indexOf(value))}
          onSelect={(item) => {
            onChange(item.value);
            setOpen(false);
          }}
        />
      ) : (
        <Box flexGrow={1} paddingX={2}>
          <Text {...textProps} inverse={isFocused}>
            {value}
          </Text>
          <Box flexGrow={1} />
          <Text {...textProps}>▼</Text>
        </Box>
      )}
    </Box>
  );
}


// A list, menu, tree or tab bar: arrow keys move the selection while it has the focus; a click
// selects (and activates) the item under the mouse.
function Choices({ lines, selected, onSelect, onActivate, horizontal, tabs, disabled, textProps }: { lines: string[]; selected: number; onSelect: (index: number) => void; onActivate?: (index: number) => void; horizontal?: boolean; tabs?: boolean; disabled?: boolean; textProps?: TextProps }) {
  const id = useId();
  const { isFocused, focus } = useFocus({ id });
  const blocked = useBlocked();
  const items = useRef<(DOMElement | null)[]>([]);
  useInput(
    (_input, key) => {
      if (!lines.length || disabled || blocked()) return;
      const prev = horizontal ? key.leftArrow : key.upArrow;
      const next = horizontal ? key.rightArrow : key.downArrow;
      if (prev) onSelect((selected + lines.length - 1) % lines.length);
      else if (next) onSelect((selected + 1) % lines.length);
      else if (key.return) onActivate?.(selected);
    },
    { isActive: isFocused },
  );
  const ref = useHit((x, y) => {
    focus(id);
    if (disabled) return;
    const i = items.current.findIndex((el) => {
      const r = rectOf(el);
      return !!r && x >= r.x && x < r.x + r.width && y >= r.y && y < r.y + r.height;
    });
    if (i < 0 || i >= lines.length) return;
    onSelect(i);
    if (!tabs) onActivate?.(i);
  });
  useReveal(ref, isFocused);
  const entries = lines.map((line, i) => (
    <Box
      key={i}
      ref={(el) => {
        items.current[i] = el;
      }}
    >
      <Text {...textProps} inverse={tabs ? i === selected && isFocused : i === selected} bold={i === selected || textProps?.bold}>
        {tabs ? " " + line + " " : line}
      </Text>
    </Box>
  ));
  if (!tabs) {
    return (
      <Box ref={ref} flexGrow={1} flexDirection={horizontal ? "row" : "column"} gap={horizontal ? 2 : 0}>
        {entries}
      </Box>
    );
  }
  // Tabs sit next to each other (one cell of padding each); the row below is the underline,
  // with the end caps of the active tab.
  const widths = lines.map((l) => [...l].length + 2);
  const before = widths.slice(0, selected).reduce((a, b) => a + b, 0);
  const span = widths[selected] ?? 0;
  const bar = "━";
  return (
    <Box ref={ref} flexGrow={1} flexDirection="column">
      <Box flexDirection="row">{entries}</Box>
      <Box height={1} overflow="hidden">
        <Box flexShrink={0}>
          <Box flexShrink={0}>
            <Text dimColor>{bar.repeat(before)}</Text>
          </Box>
          <Box flexShrink={0}>
            <Text color={textProps?.color}>{span > 1 ? "╸" + bar.repeat(span - 2) + "╺" : bar.repeat(span)}</Text>
          </Box>
          <Box flexShrink={0}>
            <Text dimColor>{bar.repeat(400)}</Text>
          </Box>
        </Box>
      </Box>
    </Box>
  );
}


function bar(value: number, max: number, width: number): string {
  const ratio = Math.max(0, Math.min(1, max ? value / max : 0));
  const filled = Math.round(ratio * width);
  return "█".repeat(filled) + "░".repeat(width - filled) + (Math.round(ratio * 100) + "%").padStart(5);
}


// Header and rows with every column as wide as its longest cell, separated by two spaces.
function tableLines(columns: string[], rows: string[][]): string[] {
  const clean = (s: string) => s.replace(/\s+/g, " ");
  const head = columns.map(clean);
  const body = rows.map((r) => head.map((_, i) => clean(r[i] ?? "")));
  const widths = head.map((c, i) => Math.max([...c].length, ...body.map((r) => [...r[i]].length)));
  const fmt = (cells: string[]) => " " + cells.map((c, i) => c + " ".repeat(widths[i] - [...c].length)).join("  ") + " ";
  return [fmt(head), ...body.map(fmt)];
}


// The error dialog (laid over the UI; Enter, Esc or a click closes it) and the log panel (Ctrl+L).
function Dialog({ entries }: { entries: ErrorEntry[] }) {
  const clip = (s: string) => (s.length > 64 ? s.slice(0, 63) + "…" : s);
  const lines = [" Error ", ...entries.flatMap((e) => e.message.split("\n").map((l) => " " + clip(l) + " ")), " Enter / Esc: close "];
  const width = Math.max(...lines.map((l) => [...l].length));
  return (
    <Box position="absolute" marginLeft={2} marginTop={1} flexDirection="column" borderStyle="double" borderColor="red">
      {lines.map((l, i) => (
        <Text key={i} bold={i === 0} color={i === 0 ? "red" : void 0}>
          {l + " ".repeat(width - [...l].length)}
        </Text>
      ))}
    </Box>
  );
}

// Bottom of the screen, laid over the UI; every line is padded so that nothing shows through.
function LogPanel({ entries, columns, rows }: { entries: LogEntry[]; columns: number; rows: number }) {
  const inner = Math.max(1, columns - 2);
  const fit = (s: string) => {
    const t = [...s].slice(0, inner).join("");
    return t + " ".repeat(inner - [...t].length);
  };
  const shown = entries.slice(-6);
  return (
    <Box position="absolute" marginTop={Math.max(0, rows - 9)} width={columns} flexDirection="column" borderStyle="single" borderColor="gray">
      <Text bold>{fit(" Log (Ctrl+L closes) ")}</Text>
      {Array.from({ length: 6 }, (_, i) => {
        const e = shown[i];
        return (
          <Text key={i} color={e && e.level === "error" ? "red" : e && e.level === "warning" ? "yellow" : void 0}>
            {fit(e ? " [" + e.level + "] " + e.message.replace(/\s+/g, " ") : "")}
          </Text>
        );
      })}
    </Box>
  );
}


const SPECS: HandleSpec[] = [
  { tag: "status", type: "Text", states: ["active", "hidden"], state: "active", props: { text: { type: "str", value: "Ready" } } },
  { tag: "name_input", type: "TextInput", states: ["active", "muted", "readonly", "hidden"], state: "active", props: { value: { type: "str", value: "" }, placeholder: { type: "str", value: "your name" } } },
  { tag: "submit_btn", type: "Button", states: ["active", "muted", "hidden"], state: "active", props: { label: { type: "str", value: "Send" } } },
  { tag: "agree", type: "Checkbox", states: ["active", "muted", "readonly", "hidden"], state: "active", props: { checked: { type: "bool", value: false }, label: { type: "str", value: "I agree" } } },
  { tag: "color", type: "Select", states: ["active", "muted", "readonly", "hidden"], state: "active", props: { value: { type: "str", value: "Red" }, options: { type: "str_list", value: ["Red", "Green", "Blue"] } } },
  { tag: "progress", type: "ProgressBar", states: ["active", "muted", "hidden"], state: "active", props: { value: { type: "float", value: 0 }, max: { type: "float", value: 100 } } },
  { tag: "results", type: "Table", states: ["active", "muted", "readonly", "hidden"], state: "active", props: { columns: { type: "str_list", value: ["Column 1", "Column 2"] }, rows: { type: "rows", value: [["Cell 1", "Cell 2"], ["Cell 3", "Cell 4"]] } } },
  { tag: "files", type: "List", states: ["active", "muted", "readonly", "hidden"], state: "active", props: { items: { type: "str_list", value: ["Item 1", "Item 2", "Item 3"] }, selected: { type: "int", value: 0 } } },
  { tag: "pages", type: "Tabs", states: ["active", "muted", "readonly", "hidden"], state: "active", props: { active_tab: { type: "int", value: 0 } } },
  { tag: "panel", type: "Box", states: ["active", "hidden"], state: "active", props: {  } },
  { tag: "inner", type: "Text", states: ["active", "hidden"], state: "active", props: { text: { type: "str", value: "Inside the panel" } } },
  { tag: "confirm", type: "Modal", states: ["active", "hidden"], state: "active", props: { title: { type: "str", value: "Sure?" } }, open: false },
];

/** The program API of this design: one handle per code name. */
export class Ui extends UiBase {
  readonly status: TextHandle;
  readonly nameInput: TextInputHandle;
  readonly submitBtn: ButtonHandle;
  readonly agree: CheckboxHandle;
  readonly color: SelectHandle;
  readonly progress: ProgressBarHandle;
  readonly results: TableHandle;
  readonly files: ListHandle;
  readonly pages: TabsHandle;
  readonly panel: ContainerHandle;
  readonly inner: TextHandle;
  readonly confirm: ModalHandle;
  constructor(options?: UiOptions) {
    super(SPECS, options);
    this.status = new TextHandle(this.core, "status");
    this.nameInput = new TextInputHandle(this.core, "name_input");
    this.submitBtn = new ButtonHandle(this.core, "submit_btn");
    this.agree = new CheckboxHandle(this.core, "agree");
    this.color = new SelectHandle(this.core, "color");
    this.progress = new ProgressBarHandle(this.core, "progress");
    this.results = new TableHandle(this.core, "results");
    this.files = new ListHandle(this.core, "files");
    this.pages = new TabsHandle(this.core, "pages");
    this.panel = new ContainerHandle(this.core, "panel");
    this.inner = new TextHandle(this.core, "inner");
    this.confirm = new ModalHandle(this.core, "confirm");
  }
  protected element(): ReactElement {
    return <App ui={this} />;
  }
}

export function App({ ui }: { ui: Ui }) {
  const core = ui.core;
  useSyncExternalStore(core.subscribe, core.snapshot);
  useEffect(() => ui.markReady(), [ui]);
  // The root fills the terminal and follows its size.
  const { stdout } = useStdout();
  const { stdin } = useStdin();
  const measure = () => ({ columns: stdout.columns || 80, rows: stdout.rows || 24 });
  const [size, setSize] = useState(measure);
  const { columns: cols, rows } = size;
  useEffect(() => {
    const onResize = () => setSize(measure());
    onResize();
    stdout.on("resize", onResize);
    return () => {
      stdout.off("resize", onResize);
    };
  }, [stdout]);
  // Mouse reporting: clicks are taken out of the input and hit-tested against the elements.
  useEffect(() => ui.attachTerminal(stdin, stdout), [ui, stdin, stdout]);
  useInput((input, key) => {
    if (core.pending.length) {
      // Enter or Esc closes the dialog (after this key has been seen by everything else).
      if (key.return || key.escape) setImmediate(() => core.dismissDialog());
      return;
    }
    if (input === "q" && !typing) ui.stop();
    if (key.ctrl && input === "l") core.toggleLog();
    // Scrolling: PageUp/PageDown always, Home/End unless a text field has the focus.
    if (key.pageUp) core.scrollBy(-Math.max(1, core.viewHeight - 1));
    else if (key.pageDown) core.scrollBy(Math.max(1, core.viewHeight - 1));
    else if (!typing && key.home) core.scrollTo(0);
    else if (!typing && key.end) core.scrollTo(core.maxScroll());
    if (key.escape) {
      core.setOpen("confirm", false);
    }
  });
  return (
    <CoreContext.Provider value={core}>
      <Box flexDirection="column">
          <Box flexDirection="column" width={cols} height={rows} overflow="hidden" padding={1} borderStyle="single" borderColor="#f8f8f2">
            <ScrollArea flexDirection="column" alignItems="flex-start">
              {core.state("status") !== "hidden" && (
                <Box flexShrink={0}>
                  <Text color="#f8f8f2">{core.str("status", "text")}</Text>
                </Box>
              )}
              {core.state("name_input") !== "hidden" && (
                <Box width={20} flexShrink={0} borderStyle="single" borderColor="#f8f8f2">
                  <Field value={core.str("name_input", "value")} onChange={(v: string) => { if (core.user("name_input", "value", v, "change")) { handleChange(); } }} onSubmit={() => { core.fire("name_input", "submit", core.str("name_input", "value")); }} placeholder={core.str("name_input", "placeholder")} textProps={{ color: "#f8f8f2", dimColor: core.state("name_input") === "muted" }} />
                </Box>
              )}
              {core.state("submit_btn") !== "hidden" && (
                <Box flexShrink={0} borderStyle="round" borderColor="#f8f8f2" minWidth={16}>
                  <Focusable center onPress={() => { if (core.fire("submit_btn", "click")) { handleClick(); } }}>
                    {(focused) => (
                      <Text bold color="#f8f8f2" dimColor={core.state("submit_btn") === "muted"} inverse={focused}>{" " + core.str("submit_btn", "label") + " "}</Text>
                    )}
                  </Focusable>
                </Box>
              )}
              {core.state("agree") !== "hidden" && (
                <Box flexShrink={0}>
                  <Focusable onPress={() => { if (core.user("agree", "checked", !core.bool("agree", "checked"), "change")) { handleChange(); } }}>
                    {(focused) => (
                      <Text color="#f8f8f2" dimColor={core.state("agree") === "muted"} inverse={focused}>
                        <Text color={core.bool("agree", "checked") ? "#50fa7b" : "#f8f8f2"}>{"[" + (core.bool("agree", "checked") ? "✓" : " ") + "]"}</Text>
                        <Text color="#f8f8f2">{" " + core.str("agree", "label")}</Text>
                      </Text>
                    )}
                  </Focusable>
                </Box>
              )}
              {core.state("color") !== "hidden" && (
                <Box flexShrink={0} width="100%" borderStyle="single" borderColor="#f8f8f2">
                  <Dropdown options={core.list("color", "options")} value={core.str("color", "value")} onChange={(v: string) => { if (core.user("color", "value", v, "change")) { handleChange(); } }} disabled={core.state("color") !== "active"} textProps={{ color: "#f8f8f2", dimColor: core.state("color") === "muted" }} />
                </Box>
              )}
              {core.state("progress") !== "hidden" && (
                <Box width={20} flexShrink={0} borderStyle="single" borderColor="#f8f8f2">
                  <Text color="#f8f8f2" dimColor={core.state("progress") === "muted"}>{bar(core.num("progress", "value"), core.num("progress", "max"), 13)}</Text>
                </Box>
              )}
              {core.state("results") !== "hidden" && (
                <Box flexShrink={0} borderStyle="single" borderColor="#f8f8f2">
                  <Box flexDirection="column">
                    {tableLines(core.list("results", "columns"), core.rows("results", "rows")).map((line, i) => (
                      <Text key={i} color="#f8f8f2" dimColor={core.state("results") === "muted"} bold={i === 0}>{line}</Text>
                    ))}
                  </Box>
                </Box>
              )}
              {core.state("files") !== "hidden" && (
                <Box flexShrink={0} width="100%" borderStyle="single" borderColor="#f8f8f2">
                  <Choices lines={core.list("files", "items")} selected={core.num("files", "selected")} onSelect={(i: number) => { core.user("files", "selected", i); }} onActivate={() => { if (core.fire("files", "select", core.num("files", "selected"))) { handleSelect(); } }} disabled={core.state("files") !== "active"} textProps={{ color: "#f8f8f2", dimColor: core.state("files") === "muted" }} />
                </Box>
              )}
              {core.state("pages") !== "hidden" && (
                <Box flexShrink={0} width="100%">
                  <Choices lines={["⌂ Dashboard", "Agent ● ^1", "QA Team ^2"]} selected={core.num("pages", "active_tab")} onSelect={(i: number) => { core.user("pages", "active_tab", i, "change"); }} horizontal tabs disabled={core.state("pages") !== "active"} textProps={{ color: "#f8f8f2", dimColor: core.state("pages") === "muted" }} />
                </Box>
              )}
              {core.state("panel") !== "hidden" && (
                <Box flexDirection="column" gap={1} alignItems="flex-start" flexShrink={0} padding={1} borderStyle="single" borderColor="#f8f8f2">
                  {core.state("inner") !== "hidden" && (
                    <Box flexShrink={0}>
                      <Text color="#f8f8f2">{core.str("inner", "text")}</Text>
                    </Box>
                  )}
                </Box>
              )}
              {core.isOpen("confirm") && core.state("confirm") !== "hidden" && (
                <ModalBox alignItems="flex-start" width={40} height={12} flexShrink={0} backgroundColor="#21222c" padding={2} borderStyle="double" borderColor="#f8f8f2" position="absolute" marginLeft={6} marginTop={16} flexDirection="column">
                  <Text bold color="#f8f8f2" backgroundColor="#21222c">{core.str("confirm", "title")}</Text>
                  <Box flexShrink={0}>
                    <Text color="#f8f8f2">{"Really?"}</Text>
                  </Box>
                </ModalBox>
              )}
            </ScrollArea>
          </Box>
        {core.logOpen ? <LogPanel entries={core.logEntries} columns={cols} rows={rows} /> : null}
        {core.pending.length ? <Dialog entries={core.pending} /> : null}
      </Box>
    </CoreContext.Provider>
  );
}

// Started directly (npm start): show the UI until it is closed.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const ui = new Ui();
  await ui.start();
  await ui.wait();
}
